import base64

def b64_decode_padded(data: str) -> bytes:
    pad = (-len(data)) % 4
    return base64.b64decode(data + ('=' * pad))

print(b64_decode_padded('SGVsbG8='))

def atbash(text: str) -> str:
    out = []
    for ch in text:
        if 'A' <= ch <= 'Z':
            out.append(chr(ord('Z') - (ord(ch) - ord('A'))))
        elif 'a' <= ch <= 'z':
            out.append(chr(ord('z') - (ord(ch) - ord('a'))))
        else:
            out.append(ch)
    return ''.join(out)

print(atbash('GSV XLMW'))

from pathlib import Path
import re

def find_ascii_strings(path: str, min_len: int = 6):
    data = Path(path).read_bytes()
    for match in re.finditer(rb'[ -~]{%d,}' % min_len, data):
        yield match.group().decode('ascii', errors='ignore')

for s in find_ascii_strings('clue.png'):
    print(s)

def vigenere_decrypt(cipher: str, key: str) -> str:
    key = ''.join(ch for ch in key.upper() if ch.isalpha())
    out = []
    ki = 0
    for ch in cipher:
        if ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            shift = ord(key[ki % len(key)]) - ord('A')
            out.append(chr(base + (ord(ch.upper()) - ord('A') - shift) % 26))
            ki += 1
        else:
            out.append(ch)
    return ''.join(out)

print(vigenere_decrypt('LXFOPVEFRNHR', 'LEMON'))
